def interior_fill(grid):
    h=len(grid); w=len(grid[0])
    out=[row[:] for row in grid]
    from collections import Counter
    cnt=Counter(v for row in grid for v in row)
    bg=cnt.most_common(1)[0][0]
    seen=set(); comps=[]
    for i in range(h):
        for j in range(w):
            v=grid[i][j]
            if v==bg or (i,j) in seen: continue
            stack=[(i,j)]; comp=[]
            while stack:
                a,b=stack.pop()
                if (a,b) in seen or grid[a][b]!=v: continue
                seen.add((a,b)); comp.append((a,b))
                for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
                    na,nb=a+da,b+db
                    if 0<=na<h and 0<=nb<w: stack.append((na,nb))
            comps.append((v,comp))
    for v,comp in comps:
        rs=[p[0] for p in comp]; cs=[p[1] for p in comp]
        top,bot,left,right=min(rs),max(rs),min(cs),max(cs)
        area=(bot-top-1)*(right-left-1)
        if area<=0: continue
        fill=7 if area%2==1 else 2
        for i in range(top+1,bot):
            for j in range(left+1,right):
                if grid[i][j]!=v:
                    out[i][j]=fill
    return out

